"""LeadHunter canonical dashboard V10: responsive workspace + saved searches."""
from fastapi import Header, HTTPException, Query
import dashboard_v6 as _base
router=_base.router

def auth(a): _base.req(a)

@router.get('/dashboard/api/searches')
async def searches(authorization:str|None=Header(default=None),limit:int=Query(30,ge=1,le=100)):
    auth(authorization); db=_base.Database(); return {'ok':True,'searches':await db.list_searches(limit)}

@router.get('/dashboard/api/searches/{search_id}/leads')
async def search_leads(search_id:int,authorization:str|None=Header(default=None),limit:int=Query(1000,ge=1,le=1000)):
    auth(authorization); db=_base.Database(); s=await db.get_search(search_id)
    if not s: raise HTTPException(404,'Search not found')
    leads=await db.list_search_results(s.get('city'),s.get('industry'),limit); return {'ok':True,'search':s,'leads':leads,'count':len(leads)}

@router.get('/dashboard/api/analytics')
async def analytics(authorization:str|None=Header(default=None)):
    auth(authorization); db=_base.Database(); leads=await db.list_leads(None,1000,0); searches=await db.list_searches(100)
    q=sum(x.get('status') in {'QUALIFIED','CONTACTED','RESPONDED','MEETING','PROPOSAL','NEGOTIATION','WON'} for x in leads); c=sum(x.get('status') in {'CONTACTED','RESPONDED','MEETING','PROPOSAL','NEGOTIATION','WON'} for x in leads); w=sum(x.get('status')=='WON' for x in leads); h=sum(x.get('priority')=='HOT' for x in leads)
    def counts(key):
        d={}
        for x in leads: d[str(x.get(key) or 'Unknown')]=d.get(str(x.get(key) or 'Unknown'),0)+1
        return [{'name':k,'count':v} for k,v in sorted(d.items(),key=lambda z:z[1],reverse=True)[:8]]
    d={}
    for x in leads:
        for s in x.get('recommended_services') or []: d[str(s)]=d.get(str(s),0)+1
    return {'ok':True,'totals':{'leads':len(leads),'qualified':q,'contacted':c,'won':w,'hot':h},'conversion':{'qualified_rate':round(q/len(leads)*100,1) if leads else 0,'contact_rate':round(c/len(leads)*100,1) if leads else 0,'win_rate':round(w/c*100,1) if c else 0},'cities':counts('city'),'industries':counts('industry'),'services':[{'name':k,'count':v} for k,v in sorted(d.items(),key=lambda z:z[1],reverse=True)[:8]],'searches':searches[:10]}

@router.get('/dashboard/api/outreach')
async def outreach(authorization:str|None=Header(default=None),limit:int=Query(30,ge=1,le=100)):
    auth(authorization); db=_base.Database(); rows=[x for x in await db.list_leads(None,1000,0) if x.get('status') in {'NEW','RESEARCHED','QUALIFIED'}]; rows.sort(key=lambda x:(0 if x.get('priority')=='HOT' else 1 if x.get('priority')=='HIGH' else 2,-int(x.get('score',0) or 0))); return {'ok':True,'leads':rows[:limit]}

